//nolint:testpackage // we need to have access for Controller for this test
package controller

import (
	"net/http"
	"testing"

	"github.com/cirruslabs/orchard/internal/responder"
	v1pkg "github.com/cirruslabs/orchard/pkg/resource/v1"
	"github.com/gin-gonic/gin"
	"github.com/stretchr/testify/require"
)

func TestAuthorizeInsecureAuthDisabled(t *testing.T) {
	ctx := &gin.Context{}
	controller := Controller{insecureAuthDisabled: true}

	require.Nil(t, controller.authorize(ctx, v1pkg.ServiceAccountRoleAdminWrite))
}

func TestAuthorizeUnauthenticated(t *testing.T) {
	ctx := &gin.Context{}
	controller := Controller{}

	require.Equal(t, responder.Code(http.StatusUnauthorized), controller.authorize(ctx))
}

func TestAuthorizeAuthenticatedNoRoles(t *testing.T) {
	ctx := &gin.Context{}
	ctx.Set(ctxServiceAccountKey, &v1pkg.ServiceAccount{})
	controller := Controller{}

	const requiredRole = v1pkg.ServiceAccountRoleAdminWrite

	require.Equal(t, responder.JSON(http.StatusUnauthorized, NewErrorResponse("all of the following roles must be present: %s", requiredRole)),
		controller.authorize(ctx, requiredRole))
}

func TestAuthorizeAuthenticatedHasRoles(t *testing.T) {
	ctx := &gin.Context{}
	const requiredRole = v1pkg.ServiceAccountRoleAdminWrite
	ctx.Set(ctxServiceAccountKey, &v1pkg.ServiceAccount{Roles: []v1pkg.ServiceAccountRole{requiredRole}})
	controller := Controller{}

	require.Nil(t, controller.authorize(ctx, requiredRole))
}

//nolint:testpackage // we need to test unexported exec helpers
package controller

import (
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/cirruslabs/orchard/internal/controller/sshexec"
	"github.com/gin-gonic/gin"
	"github.com/stretchr/testify/require"
)

func TestParseExecInteractive(t *testing.T) {
	for _, test := range []struct {
		name        string
		query       string
		interactive bool
		errContains string
	}{
		{
			name:        "default false",
			interactive: false,
		},
		{
			name:        "interactive true",
			query:       "interactive=true",
			interactive: true,
		},
		{
			name:        "stdin alias true",
			query:       "stdin=true",
			interactive: true,
		},
		{
			name:        "matching values accepted",
			query:       "interactive=true&stdin=true",
			interactive: true,
		},
		{
			name:        "conflicting values rejected",
			query:       "interactive=true&stdin=false",
			errContains: "cannot conflict",
		},
		{
			name:        "invalid interactive rejected",
			query:       "interactive=maybe",
			errContains: "interactive",
		},
		{
			name:        "invalid stdin rejected",
			query:       "stdin=maybe",
			errContains: "stdin",
		},
	} {
		t.Run(test.name, func(t *testing.T) {
			interactive, err := parseExecInteractive(execQueryContext(test.query))
			if test.errContains != "" {
				require.ErrorContains(t, err, test.errContains)

				return
			}

			require.NoError(t, err)
			require.Equal(t, test.interactive, interactive)
		})
	}
}

func TestParseExecOptions(t *testing.T) {
	options, runCommand, err := parseExecOptions(
		execQueryContext("interactive=true&tty=true&rows=24&cols=80&env[GREETING]=hello&workdir=/tmp"),
		"printf '%s' \"$GREETING\"",
	)
	require.NoError(t, err)
	require.Equal(t, sshexec.Options{
		Interactive: true,
		TTY:         true,
		Rows:        24,
		Cols:        80,
		Env:         map[string]string{"GREETING": "hello"},
		Workdir:     "/tmp",
	}, options)
	require.Equal(t, "cd '/tmp' || exit $?\nexport GREETING='hello'\nprintf '%s' \"$GREETING\"", runCommand)
}

func TestParseExecOptionsRejectsPartialTTYSize(t *testing.T) {
	_, _, err := parseExecOptions(execQueryContext("tty=true&rows=24"), "echo hello")
	require.ErrorContains(t, err, "provided together")
}

func execQueryContext(query string) *gin.Context {
	ctx, _ := gin.CreateTestContext(httptest.NewRecorder())
	ctx.Request = httptest.NewRequest(http.MethodGet, "/?"+query, nil)

	return ctx
}

package tests_test

import (
	"context"
	"github.com/cirruslabs/orchard/internal/tests/devcontroller"
	"github.com/cirruslabs/orchard/internal/tests/wait"
	v1 "github.com/cirruslabs/orchard/pkg/resource/v1"
	"github.com/stretchr/testify/require"
	"testing"
	"time"
)

func TestImplicitCPUMemory(t *testing.T) {
	ctx := context.Background()

	// Create a development environment
	devClient, _, _ := devcontroller.StartIntegrationTestEnvironmentWithAdditionalOpts(t,
		false, nil,
		true, nil,
	)

	// Create a worker with default CPU and memory values
	const workerName = "worker"

	_, err := devClient.Workers().Create(ctx, v1.Worker{
		Meta: v1.Meta{
			Name: workerName,
		},
		Resources: map[string]uint64{
			v1.ResourceTartVMs: 2,
		},
		DefaultCPU:    12,
		DefaultMemory: 3456,
	})
	require.NoError(t, err)

	// Create a VM with implicit CPU and memory
	vmName := "test-vm"

	require.NoError(t, devClient.VMs().Create(ctx, &v1.VM{
		Meta: v1.Meta{
			Name: vmName,
		},
		Image:  "example.com/doesnt/matter:latest",
		Status: v1.VMStatusPending,
	}))

	// Wait for the VM to be assigned
	require.True(t, wait.Wait(2*time.Minute, func() bool {
		vm, err := devClient.VMs().Get(context.Background(), vmName)
		require.NoError(t, err)

		t.Logf("Waiting for the VM %s to be assigned to a worker", vmName)

		return vm.Worker == workerName
	}), "VM was %s expected to be assigned to the worker %q, but was assigned to the worker %q",
		vmName, workerName)

	// Ensure that the VM is using default CPU and memory values from the worker
	vm, err := devClient.VMs().Get(context.Background(), vmName)
	require.NoError(t, err)
	require.EqualValues(t, 12, vm.AssignedCPU)
	require.EqualValues(t, 3456, vm.AssignedMemory)
}

//nolint:testpackage // The regression exercises the unexported scheduler reconciliation loop.
package scheduler

import (
	"testing"
	"time"

	"github.com/cirruslabs/orchard/internal/controller/notifier"
	storepkg "github.com/cirruslabs/orchard/internal/controller/store"
	"github.com/cirruslabs/orchard/internal/controller/store/badger"
	v1 "github.com/cirruslabs/orchard/pkg/resource/v1"
	"github.com/stretchr/testify/require"
	"go.uber.org/zap"
)

func TestSchedulingLoopSkipsOvercommittedWorker(t *testing.T) {
	logger := zap.NewNop().Sugar()

	store, err := badger.NewBadgerStore(t.TempDir(), true, logger)
	require.NoError(t, err)

	var worker v1.Worker
	worker.Name = "worker-a"
	worker.LastSeen = time.Now()
	worker.MachineID = "machine-a"
	worker.Resources = v1.Resources{v1.ResourceTartVMs: 2}
	worker.Arch = v1.ArchitectureARM64
	worker.Runtime = v1.RuntimeTart

	newPendingVM := func(name string) v1.VM {
		var vm v1.VM
		vm.Name = name
		vm.CreatedAt = time.Now()
		vm.UID = name + "-uid"
		vm.Status = v1.VMStatusPending
		vm.Resources = v1.Resources{v1.ResourceTartVMs: 1}
		vm.Arch = v1.ArchitectureARM64
		vm.Runtime = v1.RuntimeTart
		vm.PowerState = v1.PowerStateRunning
		vm.Conditions = []v1.Condition{{
			Type:  v1.ConditionTypeScheduled,
			State: v1.ConditionStateFalse,
		}}

		return vm
	}

	assignedVM := func(name string, status v1.VMStatus) v1.VM {
		vm := newPendingVM(name)
		vm.Worker = worker.Name
		vm.Status = status
		vm.Conditions[0].State = v1.ConditionStateTrue

		return vm
	}

	pending := newPendingVM("pending-vm")

	var settings v1.ClusterSettings
	settings.SchedulerProfile = v1.SchedulerProfileOptimizeUtilization

	err = store.Update(func(txn storepkg.Transaction) error {
		if err := txn.SetClusterSettings(settings); err != nil {
			return err
		}

		if err := txn.SetWorker(worker); err != nil {
			return err
		}

		vms := []v1.VM{
			assignedVM("running-first", v1.VMStatusRunning),
			assignedVM("running-second", v1.VMStatusRunning),
			assignedVM("failed-third", v1.VMStatusFailed),
			pending,
		}

		for _, vm := range vms {
			if err := txn.SetVM(vm); err != nil {
				return err
			}
		}

		return nil
	})
	require.NoError(t, err)

	scheduler, err := NewScheduler(store, notifier.NewNotifier(logger), time.Minute, logger)
	require.NoError(t, err)

	numWorkers, numVMs, err := scheduler.schedulingLoopIteration()
	require.NoError(t, err)
	require.Equal(t, 1, numWorkers)
	require.Equal(t, 4, numVMs)

	err = store.View(func(txn storepkg.Transaction) error {
		currentVM, err := txn.GetVM(pending.Name)
		require.NoError(t, err)
		require.False(t, currentVM.IsScheduled())
		require.Empty(t, currentVM.Worker)

		return nil
	})
	require.NoError(t, err)
}

type replaceAfterViewStore struct {
	storepkg.Store

	replacement v1.VM
}

func (store *replaceAfterViewStore) View(cb func(storepkg.Transaction) error) error {
	if err := store.Store.View(cb); err != nil {
		return err
	}
	return store.Update(func(txn storepkg.Transaction) error {
		return txn.SetVM(store.replacement)
	})
}

func TestHealthCheckSkipsUnscheduledReplacement(t *testing.T) {
	logger := zap.NewNop().Sugar()
	store, err := badger.NewBadgerStore(t.TempDir(), true, logger)
	require.NoError(t, err)

	var replacement v1.VM
	replacement.Name = "replaced-vm"
	replacement.UID = "replacement-uid"
	replacement.Status = v1.VMStatusPending

	original := replacement
	original.UID = "original-uid"
	original.Status = v1.VMStatusRunning
	original.Worker = "worker-a"
	original.Conditions = []v1.Condition{{
		Type:  v1.ConditionTypeScheduled,
		State: v1.ConditionStateTrue,
	}}
	require.NoError(t, store.Update(func(txn storepkg.Transaction) error {
		return txn.SetVM(original)
	}))

	scheduler, err := NewScheduler(&replaceAfterViewStore{Store: store, replacement: replacement},
		notifier.NewNotifier(logger), time.Minute, logger)
	require.NoError(t, err)
	_, err = scheduler.healthCheckingLoopIteration()
	require.NoError(t, err)

	require.NoError(t, store.View(func(txn storepkg.Transaction) error {
		current, err := txn.GetVM(replacement.Name)
		require.NoError(t, err)
		require.Equal(t, replacement.UID, current.UID)
		require.Equal(t, v1.VMStatusPending, current.Status)
		require.Empty(t, current.StatusMessage)
		return nil
	}))
}

package bootstraptoken

import (
	"crypto/x509"
	"encoding/base64"
	"encoding/pem"
	"errors"
	"fmt"
	"strings"
)

var (
	ErrFailedToCreateBootstrapToken = errors.New("failed to create bootstrap token")
	ErrInvalidBootstrapTokenFormat  = errors.New("invalid bootstrap token format")

	encoding = base64.RawURLEncoding
)

const (
	versionPrefix = "orchard-bootstrap-token-v"
	version       = 0
)

type BootstrapToken struct {
	version             int
	certificate         *x509.Certificate
	rawCertificate      []byte
	serviceAccountName  string
	serviceAccountToken string
}

func New(rawCertificate []byte, serviceAccountName string, serviceAccountToken string) (*BootstrapToken, error) {
	if serviceAccountName == "" {
		return nil, fmt.Errorf("%w: empty service account name", ErrFailedToCreateBootstrapToken)
	}

	if serviceAccountToken == "" {
		return nil, fmt.Errorf("%w: empty service account token", ErrFailedToCreateBootstrapToken)
	}

	// Optionally parse a certificate
	var certificate *x509.Certificate
	var err error

	if len(rawCertificate) != 0 {
		block, _ := pem.Decode(rawCertificate)
		if block == nil {
			return nil, fmt.Errorf("%w: failed to parse certificate: expected a PEM format",
				ErrFailedToCreateBootstrapToken)
		}

		certificate, err = x509.ParseCertificate(block.Bytes)
		if err != nil {
			return nil, fmt.Errorf("%w: failed to parse certificate: %v",
				ErrFailedToCreateBootstrapToken, err)
		}
	}

	return &BootstrapToken{
		version:             version,
		certificate:         certificate,
		serviceAccountName:  serviceAccountName,
		serviceAccountToken: [REDACTED],
		rawCertificate:      rawCertificate,
	}, nil
}

func NewFromString(rawBootstrapToken string) (*BootstrapToken, error) {
	splits := strings.Split(rawBootstrapToken, ".")

	currentVersionString := fmt.Sprintf("%s%d", versionPrefix, version)

	if splits[0] != currentVersionString {
		return nil, fmt.Errorf("%w: invalid version string or unsupported version",
			ErrInvalidBootstrapTokenFormat)
	}

	if len(splits) < 3 {
		return nil, fmt.Errorf("%w: missing service account credentials", ErrInvalidBootstrapTokenFormat)
	}

	if len(splits) > 4 {
		return nil, fmt.Errorf("%w: extraneous data", ErrInvalidBootstrapTokenFormat)
	}

	serviceAccountName, err := encoding.DecodeString(splits[1])
	if err != nil {
		return nil, fmt.Errorf("%w: failed to decode service account name: %v",
			ErrInvalidBootstrapTokenFormat, err)
	}
	serviceAccountToken, err := encoding.DecodeString(splits[2])
	if err != nil {
		return nil, fmt.Errorf("%w: failed to decode service account token: %v",
			ErrInvalidBootstrapTokenFormat, err)
	}

	// Optionally parse the certificate
	var certificate *x509.Certificate
	var rawCertificate []byte

	if len(splits) == 4 {
		rawCertificate, err = encoding.DecodeString(splits[3])
		if err != nil {
			return nil, fmt.Errorf("%w: failed to decode certificate: %v",
				ErrInvalidBootstrapTokenFormat, err)
		}

		block, _ := pem.Decode(rawCertificate)

		certificate, err = x509.ParseCertificate(block.Bytes)
		if err != nil {
			return nil, fmt.Errorf("%w: failed to parse certificate: %v",
				ErrFailedToCreateBootstrapToken, err)
		}
	}

	return &BootstrapToken{
		version:             version,
		certificate:         certificate,
		rawCertificate:      rawCertificate,
		serviceAccountName:  string(serviceAccountName),
		serviceAccountToken: [REDACTED],
	}, nil
}

func (bt *BootstrapToken) String() string {
	var certificatePart string

	// Certificate is optional
	if len(bt.rawCertificate) != 0 {
		certificatePart = fmt.Sprintf(".%s", encoding.EncodeToString(bt.rawCertificate))
	}

	return fmt.Sprintf("%s%d.%s.%s%s",
		versionPrefix,
		version,
		encoding.EncodeToString([]byte(bt.serviceAccountName)),
		encoding.EncodeToString([]byte(bt.serviceAccountToken)),
		certificatePart,
	)
}

func (bt *BootstrapToken) ServiceAccountName() string {
	return bt.serviceAccountName
}

func (bt *BootstrapToken) ServiceAccountToken() string {
	return bt.serviceAccountToken
}

func (bt *BootstrapToken) Certificate() *x509.Certificate {
	return bt.certificate
}

package get

import (
	"fmt"
	"github.com/cirruslabs/orchard/internal/bootstraptoken"
	"github.com/cirruslabs/orchard/internal/config"
	"github.com/cirruslabs/orchard/pkg/client"
	"github.com/spf13/cobra"
)

func newGetBootstrapTokenCommand() *cobra.Command {
	command := &cobra.Command{
		Use:   "bootstrap-token NAME",
		Short: "Retrieve a bootstrap token for the specified service account",
		RunE:  runGetBootstrapToken,
		Args:  cobra.ExactArgs(1),
	}

	return command
}

func runGetBootstrapToken(cmd *cobra.Command, args []string) error {
	name := args[0]

	configHandle, err := config.NewHandle()
	if err != nil {
		return err
	}

	defaultContext, err := configHandle.DefaultContext()
	if err != nil {
		return err
	}

	client, err := client.New()
	if err != nil {
		return err
	}

	serviceAccount, err := client.ServiceAccounts().Get(cmd.Context(), name)
	if err != nil {
		return err
	}

	bootstrapToken, err := bootstraptoken.New(defaultContext.Certificate, serviceAccount.Name, serviceAccount.Token)
	if err != nil {
		return err
	}

	fmt.Println(bootstrapToken)

	return nil
}

package controller

import (
	"crypto/tls"
	"fmt"
	"os"
	"strings"

	"github.com/cirruslabs/orchard/internal/certificatefingerprint"
	"github.com/cirruslabs/orchard/internal/controller"
	v1 "github.com/cirruslabs/orchard/pkg/resource/v1"
	"github.com/pterm/pterm"
	"github.com/samber/lo"
	"github.com/sethvargo/go-password/password"
)

const BootstrapContextName = "bootstrap-context"
const BootstrapAdminName = "bootstrap-admin"

func Bootstrap(controllerInstance *controller.Controller, controllerCert tls.Certificate) (string, string, error) {
	// Determine if we need to do anything at all
	orchardBootstrapAdminToken, orchardBootstrapAdminTokenPresent := os.LookupEnv("ORCHARD_BOOTSTRAP_ADMIN_TOKEN")

	serviceAccounts, err := controllerInstance.ServiceAccounts()
	if err != nil {
		return "", "", fmt.Errorf("failed to retrieve the number of service accounts: %w", err)
	}

	if len(serviceAccounts) != 0 && !orchardBootstrapAdminTokenPresent {
		// No bootstrap is needed because there are service accounts
		// present in the database (so it's not the first start)
		// and no bootstrap admin token change is requested
		//
		// However, if the BootstrapAdminName service account still exists,
		// return its credentials. We'll use them for updating the
		// BootstrapContextName context.
		if serviceAccount, ok := lo.Find(serviceAccounts, func(serviceAccount v1.ServiceAccount) bool {
			return serviceAccount.Name == BootstrapAdminName
		}); ok {
			return serviceAccount.Name, serviceAccount.Token, nil
		}

		return "", "", nil
	}

	// Generate a bootstrap admin token if not present in the environment variable
	if !orchardBootstrapAdminTokenPresent {
		passwordGenerator, err := password.NewGenerator(&password.GeneratorInput{
			LowerLetters: password.LowerLetters,
			UpperLetters: password.UpperLetters,
			Digits:       password.Digits,
			Symbols: strings.Map(func(r rune) rune {
				// Avoid generating $ and " symbols
				// as they cause issues in shell
				switch r {
				case '$', '"':
					return -1
				default:
					return r
				}
			}, password.Symbols),
		})
		if err != nil {
			return "", "", fmt.Errorf("failed to generate bootstrap admin token: "+
				"failed to initialize password generator: %w", err)
		}

		orchardBootstrapAdminToken, err = passwordGenerator.Generate(32, 10, 10,
			false, false)
		if err != nil {
			return "", "", fmt.Errorf("failed to generate bootstrap admin token: %w", err)
		}
	}

	// Ensure bootstrap admin service account exists
	if err := controllerInstance.EnsureServiceAccount(&v1.ServiceAccount{
		Meta: v1.Meta{
			Name: BootstrapAdminName,
		},
		Token: [REDACTED],
		Roles: v1.AllServiceAccountRoles(),
	}); err != nil {
		return "", "", err
	}

	// Report bootstrapping result to the user
	var reasonToDisplay string
	var serviceAccountTokenToDisplay string

	if orchardBootstrapAdminTokenPresent {
		reasonToDisplay = fmt.Sprintf("Re-created the %q service account using the token "+
			"provided in the ORCHARD_BOOTSTRAP_ADMIN_TOKEN environment variable", BootstrapAdminName)
		serviceAccountTokenToDisplay = "<hidden>"
	} else {
		reasonToDisplay = fmt.Sprintf("No service accounts found, created a new %q service "+
			"account using a randomly-generated password", BootstrapAdminName)
		serviceAccountTokenToDisplay = orchardBootstrapAdminToken
	}

	messages := []any{
		pterm.Sprintf("%s:\n", reasonToDisplay),
		pterm.Sprintln(),
		pterm.Sprintf("Service account name: %s\n", pterm.Bold.Sprint(BootstrapAdminName)),
		pterm.Sprintf("Service account token: %s\n", pterm.Bold.Sprint(serviceAccountTokenToDisplay)),
	}

	if !noTLS {
		messages = append(messages, pterm.Sprintf("Certificate SHA-256 fingerprint: %s.\n",
			pterm.Bold.Sprint(certificatefingerprint.CertificateFingerprint(controllerCert.Certificate[0]))))
	}

	pterm.Info.Print(messages...)

	return BootstrapAdminName, orchardBootstrapAdminToken, nil
}

package controller

import (
	"context"
	storepkg "github.com/cirruslabs/orchard/internal/controller/store"
	"github.com/cirruslabs/orchard/internal/responder"
	v1 "github.com/cirruslabs/orchard/pkg/resource/v1"
	"github.com/gin-gonic/gin"
	"net/http"
	"strconv"
	"time"
)

func (controller *Controller) portForwardWorker(ctx *gin.Context) responder.Responder {
	if responder := controller.authorize(ctx, v1.ServiceAccountRoleAdminWrite); responder != nil {
		return responder
	}

	// Retrieve and parse path and query parameters
	name := ctx.Param("name")

	portRaw := ctx.Query("port")
	port, err := strconv.ParseUint(portRaw, 10, 16)
	if err != nil {
		return responder.Code(http.StatusBadRequest)
	}
	if port < 1 || port > 65535 {
		return responder.Code(http.StatusBadRequest)
	}

	waitRaw := ctx.DefaultQuery("wait", "10")
	wait, err := strconv.ParseUint(waitRaw, 10, 16)
	if err != nil {
		return responder.Code(http.StatusBadRequest)
	}
	waitContext, waitContextCancel := context.WithTimeout(ctx, time.Duration(wait)*time.Second)
	defer waitContextCancel()

	var worker *v1.Worker

	if responder := controller.storeView(func(txn storepkg.Transaction) responder.Responder {
		worker, err = txn.GetWorker(name)
		if err != nil {
			return responder.Error(err)
		}

		return nil
	}); responder != nil {
		return responder
	}

	// Commence port-forwarding
	return controller.portForward(ctx, waitContext, worker.Name, "", uint32(port), "", "")
}

package controller

import (
	"net/http"

	"github.com/cirruslabs/orchard/internal/responder"
	"github.com/cirruslabs/orchard/internal/version"
	v1pkg "github.com/cirruslabs/orchard/pkg/resource/v1"
	"github.com/gin-gonic/gin"
)

func (controller *Controller) controllerInfo(ctx *gin.Context) responder.Responder {
	// Only require the service account to be valid,
	// no roles are needed to query this endpoint
	if responder := controller.authorize(ctx); responder != nil {
		return responder
	}

	capabilities := []v1pkg.ControllerCapability{
		v1pkg.ControllerCapabilityRPCV1,
		v1pkg.ControllerCapabilityVMStateEndpoint,
	}

	if controller.experimentalRPCV2 {
		capabilities = append(capabilities, v1pkg.ControllerCapabilityRPCV2)
	}

	return responder.JSON(http.StatusOK, &v1pkg.ControllerInfo{
		Version:      version.Version,
		Commit:       version.Commit,
		Capabilities: capabilities,
	})
}

package controller

import (
	"context"
	"github.com/cirruslabs/orchard/internal/controller/rendezvous"
	"github.com/cirruslabs/orchard/internal/responder"
	v1 "github.com/cirruslabs/orchard/pkg/resource/v1"
	"github.com/coder/websocket"
	"github.com/gin-gonic/gin"
	"net"
	"time"
)

func (controller *Controller) rpcPortForward(ctx *gin.Context) responder.Responder {
	if responder := controller.authorize(ctx, v1.ServiceAccountRoleComputeWrite); responder != nil {
		return responder
	}

	// Retrieve and parse path and query parameters
	session := ctx.Query("session")
	errorMessage := ctx.Query("errorMessage")

	// Perform WebSocket protocol upgrade
	wsConn, err := websocket.Accept(ctx.Writer, ctx.Request, &websocket.AcceptOptions{
		OriginPatterns: []string{"*"},
	})
	if err != nil {
		return responder.Error(err)
	}
	defer func() {
		// Ensure that we always close the accepted WebSocket connection,
		// otherwise resource leak is possible[1]
		//
		// [1]: https://github.com/coder/websocket/issues/445#issuecomment-2053792044
		_ = wsConn.CloseNow()
	}()

	// Respond with the established connection
	proxyCtx, err := controller.connRendezvous.Respond(session, rendezvous.ResultWithErrorMessage[net.Conn]{
		Result:       websocket.NetConn(ctx, wsConn, websocket.MessageBinary),
		ErrorMessage: errorMessage,
	})
	if err != nil {
		return controller.wsError(wsConn, websocket.StatusInternalError, "port forwarding RPC",
			"failure to respond with the established WebSocket connection", err)
	}

	for {
		select {
		case <-proxyCtx.Done():
			// Do not close the WebSocket connection as it should be already closed by our rendezvous party
			return responder.Empty()
		case <-time.After(controller.pingInterval):
			pingCtx, pingCtxCancel := context.WithTimeout(ctx, 5*time.Second)

			if err := wsConn.Ping(pingCtx); err != nil {
				controller.logger.Warnf("port forwarding RPC: failed to ping the worker, "+
					"connection might time out: %v", err)
			}

			pingCtxCancel()
		case <-ctx.Done():
			// Connection shouldn't be normally closed by the worker
			return controller.wsErrorNoClose("watch RPC",
				"worker unexpectedly disconnected", ctx.Err())
		}
	}
}

