package controller

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"time"

	"github.com/cirruslabs/orchard/internal/responder"
	v1 "github.com/cirruslabs/orchard/pkg/resource/v1"
	"github.com/cirruslabs/orchard/rpc"
	"github.com/coder/websocket"
	"github.com/gin-gonic/gin"
)

//nolint:protogetter // Preserve the original host-process wire conversion.
func (controller *Controller) rpcWatch(ctx *gin.Context) responder.Responder {
	if responder := controller.authorize(ctx, v1.ServiceAccountRoleComputeWrite); responder != nil {
		return responder
	}

	// Retrieve and parse path and query parameters
	workerName := ctx.Query("workerName")

	if workerName == "" {
		return responder.Error(errors.New("worker name cannot be empty"))
	}

	// Register with the worker notifier to forward requests from other
	// parts of the Orchard Controller destined to this specific worker
	workerCh, cancel := controller.workerNotifier.Register(ctx, workerName)
	defer cancel()

	// Perform WebSocket protocol upgrade
	wsConn, err := websocket.Accept(ctx.Writer, ctx.Request, &websocket.AcceptOptions{
		OriginPatterns: []string{"*"},
	})
	if err != nil {
		return responder.Error(err)
	}
	defer func() {
		// Ensure that we always close the accepted WebSocket connection,
		// otherwise resource leak is possible[1]
		//
		// [1]: https://github.com/coder/websocket/issues/445#issuecomment-2053792044
		_ = wsConn.CloseNow()
	}()

	// Ensure that pongs will be processed by reading
	// from the connection in the background
	//
	// Otherwise the wsConn.Ping() will wait forever.
	closeReadCtx := wsConn.CloseRead(ctx)

	for {
		select {
		case msg := <-workerCh:
			var watchInstruction v1.WatchInstruction

			// Perform Protocol Buffers to v1 API data structure conversion
			switch typedAction := msg.Action.(type) {
			case *rpc.WatchInstruction_PortForwardAction:
				watchInstruction.PortForwardAction = &v1.PortForwardAction{
					Session: typedAction.PortForwardAction.Session,
				}

				if target := typedAction.PortForwardAction.GetTarget(); target != nil {
					watchInstruction.PortForwardAction.Target = &v1.PortForwardTarget{}

					if hostProcess := target.GetHostProcess(); hostProcess != nil {
						watchInstruction.PortForwardAction.Target.HostProcess = &v1.PortForwardTargetHostProcess{
							VMUID: hostProcess.VmUid,
							Name:  hostProcess.Name,
						}
					}

					if tartGuestAgent := target.GetTartGuestAgent(); tartGuestAgent != nil {
						watchInstruction.PortForwardAction.Target.TartGuestAgent = &v1.PortForwardTargetTartGuestAgent{
							VMUID: tartGuestAgent.VmUid,
						}
					}
				} else {
					watchInstruction.PortForwardAction.VMUID = typedAction.PortForwardAction.VmUid
					watchInstruction.PortForwardAction.Port = uint16(typedAction.PortForwardAction.Port)
				}
			case *rpc.WatchInstruction_SyncVmsAction:
				watchInstruction.SyncVMsAction = &v1.SyncVMsAction{}
			case *rpc.WatchInstruction_ResolveIpAction:
				watchInstruction.ResolveIPAction = &v1.ResolveIPAction{
					Session: typedAction.ResolveIpAction.Session,
					VMUID:   typedAction.ResolveIpAction.VmUid,
				}
			default:
				continue
			}

			watchInstructionJSONBytes, err := json.Marshal(&watchInstruction)
			if err != nil {
				return controller.wsError(wsConn, websocket.StatusInternalError, "watch RPC",
					"failure to marshal the watch instruction", err)
			}

			if err := wsConn.Write(ctx, websocket.MessageBinary, watchInstructionJSONBytes); err != nil {
				return controller.wsError(wsConn, websocket.StatusInternalError, "watch RPC",
					"failure to write the watch instruction", err)
			}
		case <-time.After(controller.pingInterval):
			pingCtx, pingCtxCancel := context.WithTimeout(ctx, 5*time.Second)

			if err := wsConn.Ping(pingCtx); err != nil {
				controller.logger.Warnf("watch RPC: failed to ping the worker %s, "+
					"connection might time out: %v", workerName, err)
			}

			pingCtxCancel()
		case <-closeReadCtx.Done():
			// Connection shouldn't be normally closed by the worker
			return controller.wsErrorNoClose("watch RPC",
				fmt.Sprintf("worker %s unexpectedly disconnected", workerName), closeReadCtx.Err())
		case <-ctx.Done():
			// Connection shouldn't be normally closed by the worker
			return controller.wsErrorNoClose("watch RPC",
				fmt.Sprintf("worker %s unexpectedly disconnected", workerName), ctx.Err())
		}
	}
}

package controller

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"strconv"
	"time"

	"github.com/avast/retry-go/v5"
	"github.com/cirruslabs/orchard/internal/controller/sshexec"
	"github.com/cirruslabs/orchard/internal/execstream"
	"github.com/cirruslabs/orchard/internal/responder"
	v1 "github.com/cirruslabs/orchard/pkg/resource/v1"
	"github.com/coder/websocket"
	"github.com/gin-gonic/gin"
)

func (controller *Controller) execVM(ctx *gin.Context) responder.Responder {
	if responder := controller.authorizeAny(ctx, v1.ServiceAccountRoleComputeWrite,
		v1.ServiceAccountRoleComputeConnect); responder != nil {
		return responder
	}

	// Retrieve and parse path and query parameters
	name := ctx.Param("name")
	command := ctx.Query("command")
	if command == "" {
		return responder.JSON(http.StatusBadRequest,
			NewErrorResponse("\"command\" parameter cannot be empty"))
	}

	options, runCommand, err := parseExecOptions(ctx, command)
	if err != nil {
		return responder.JSON(http.StatusBadRequest, NewErrorResponse("%v", err))
	}

	waitRaw := ctx.DefaultQuery("wait", "10")
	wait, err := strconv.ParseUint(waitRaw, 10, 16)
	if err != nil {
		return responder.Code(http.StatusBadRequest)
	}

	// Look-up the VM
	waitContext, waitContextCancel := context.WithTimeout(ctx, time.Duration(wait)*time.Second)
	defer waitContextCancel()

	vm, responderImpl := controller.waitForVM(waitContext, name)
	if responderImpl != nil {
		return responderImpl
	}

	exec, err := controller.newSSHExec(waitContext, vm, options)
	if err != nil {
		return responder.JSON(http.StatusServiceUnavailable, NewErrorResponse("%v", err))
	}

	// Upgrade HTTP request to a WebSocket connection
	wsConn, err := websocket.Accept(ctx.Writer, ctx.Request, &websocket.AcceptOptions{
		OriginPatterns: []string{"*"},
	})
	if err != nil {
		_ = exec.Close()

		return responder.Error(err)
	}
	defer func() {
		// Ensure that we always close the accepted WebSocket connection,
		// otherwise resource leak is possible[1]
		//
		// [1]: https://github.com/coder/websocket/issues/445#issuecomment-2053792044
		_ = wsConn.CloseNow()
	}()

	return controller.serveExec(ctx, wsConn, exec, runCommand)
}

func (controller *Controller) newSSHExec(
	waitContext context.Context,
	vm *v1.VM,
	options sshexec.Options,
) (*sshexec.Exec, error) {
	return retry.NewWithData[*sshexec.Exec](
		retry.Context(waitContext),
		retry.DelayType(retry.FixedDelay),
		retry.Delay(time.Second),
		retry.Attempts(0),
		retry.LastErrorOnly(true),
	).Do(func() (*sshexec.Exec, error) {
		exec, err := controller.execSSHClients.newExec(vm.UID, options, func() (sshExecClient, error) {
			portForwardConn, err := controller.portForwardConnection(
				context.Background(),
				waitContext,
				vm.Worker,
				vm.UID,
				22,
				"",
				"",
			)
			if err != nil {
				return nil, err
			}

			client, err := sshexec.NewClient(portForwardConn, vm.SSHUsername(), vm.SSHPassword())
			if err != nil {
				_ = portForwardConn.Close()

				return nil, fmt.Errorf("failed to establish SSH connection to a VM: %w", err)
			}

			return client, nil
		})
		if err != nil {
			return nil, fmt.Errorf("failed to establish SSH connection to a VM: %w", err)
		}

		return exec, nil
	})
}

func (controller *Controller) serveExec(
	ctx *gin.Context,
	wsConn *websocket.Conn,
	exec *sshexec.Exec,
	command string,
) *responder.EmptyResponder {
	execContext, cancel := context.WithCancel(context.Background())
	defer func() {
		cancel()
		_ = exec.Close()
	}()

	// A bounded channel applies backpressure without dropping output. The SSH
	// runner drains stdout/stderr before sending exit, then we drain this channel.
	outgoingFrames := make(chan *execstream.Frame, 128)
	go func() {
		defer close(outgoingFrames)

		if err := exec.Run(execContext, command, outgoingFrames); err != nil && !errors.Is(err, context.Canceled) {
			select {
			case outgoingFrames <- &execstream.Frame{Type: execstream.FrameTypeError, Error: err.Error()}:
			case <-execContext.Done():
			}
		}
	}()

	readFramesErrCh := make(chan error, 1)
	go func() {
		readFramesErrCh <- readExecFrames(ctx, wsConn, exec)
	}()

	for {
		select {
		case readFramesErr := <-readFramesErrCh:
			if readFramesErr != nil {
				controller.logger.Warnf("failed to read and process exec frames from WebSocket: %v",
					readFramesErr)
			}

			return responder.Empty()
		case outgoingFrame, ok := <-outgoingFrames:
			if !ok {
				if err := wsConn.Close(websocket.StatusNormalClosure, "Command finished"); err != nil {
					controller.logger.Warnf("exec: failed to close WebSocket cleanly: %v", err)
				}

				return responder.Empty()
			}

			if err := execstream.WriteFrame(ctx, wsConn, outgoingFrame); err != nil {
				controller.logger.Warnf("failed to write exec frame to the client: %v", err)

				return responder.Empty()
			}
		case <-time.After(controller.pingInterval):
			pingCtx, pingCtxCancel := context.WithTimeout(ctx, 5*time.Second)

			if err := wsConn.Ping(pingCtx); err != nil {
				controller.logger.Warnf("exec: failed to ping the client, "+
					"connection might time out: %v", err)
			}

			pingCtxCancel()
		case <-ctx.Done():
			controller.logger.Warnf("client disconnected prematurely")

			return responder.Empty()
		}
	}
}

func parseExecOptions(ctx *gin.Context, command string) (sshexec.Options, string, error) {
	interactive, err := parseExecInteractive(ctx)
	if err != nil {
		return sshexec.Options{}, "", err
	}

	tty, err := parseExecBool(ctx, "tty")
	if err != nil {
		return sshexec.Options{}, "", err
	}
	if tty {
		interactive = true
	}

	rows, err := parseExecUint32(ctx.Query("rows"), "rows")
	if err != nil {
		return sshexec.Options{}, "", err
	}
	cols, err := parseExecUint32(ctx.Query("cols"), "cols")
	if err != nil {
		return sshexec.Options{}, "", err
	}
	if (rows == 0) != (cols == 0) {
		return sshexec.Options{}, "", errors.New("\"rows\" and \"cols\" must be provided together")
	}

	options := sshexec.Options{
		Interactive: interactive,
		TTY:         tty,
		Rows:        rows,
		Cols:        cols,
		Env:         ctx.QueryMap("env"),
		Workdir:     ctx.Query("workdir"),
	}

	runCommand, err := sshexec.CommandWithOptions(command, options)
	if err != nil {
		return sshexec.Options{}, "", err
	}

	return options, runCommand, nil
}

func parseExecInteractive(ctx *gin.Context) (bool, error) {
	interactive, err := parseExecBool(ctx, "interactive")
	if err != nil {
		return false, err
	}

	interactiveRaw, interactivePresent := ctx.GetQuery("interactive")
	stdinRaw, stdinPresent := ctx.GetQuery("stdin")
	if !stdinPresent {
		return interactive, nil
	}

	stdin, err := strconv.ParseBool(stdinRaw)
	if err != nil {
		return false, errors.New("\"stdin\" parameter must be a boolean")
	}

	if interactivePresent {
		parsedInteractive, _ := strconv.ParseBool(interactiveRaw)
		if stdin != parsedInteractive {
			return false, errors.New("\"interactive\" and \"stdin\" parameters cannot conflict")
		}
	}

	if !interactivePresent {
		interactive = stdin
	}

	return interactive, nil
}

func parseExecBool(ctx *gin.Context, name string) (bool, error) {
	raw, present := ctx.GetQuery(name)
	if !present {
		return false, nil
	}

	value, err := strconv.ParseBool(raw)
	if err != nil {
		return false, fmt.Errorf("%q parameter must be a boolean", name)
	}

	return value, nil
}

func parseExecUint32(raw string, name string) (uint32, error) {
	if raw == "" {
		return 0, nil
	}

	value, err := strconv.ParseUint(raw, 10, 32)
	if err != nil {
		return 0, fmt.Errorf("%q parameter must be an unsigned integer", name)
	}

	return uint32(value), nil
}

func readExecFrames(ctx context.Context, wsConn *websocket.Conn, exec *sshexec.Exec) error {
	stdin := exec.Stdin()
	stdinClosed := false

	for {
		var frame execstream.Frame

		messageType, payloadBytes, err := wsConn.Read(ctx)
		if err != nil {
			var closeErr websocket.CloseError
			if errors.As(err, &closeErr) && closeErr.Code == websocket.StatusNormalClosure {
				return nil
			}

			return fmt.Errorf("failed to read next frame from WebSocket: %w", err)
		}

		if messageType != websocket.MessageText {
			continue
		}

		if err := json.Unmarshal(payloadBytes, &frame); err != nil {
			return err
		}

		switch frame.Type {
		case execstream.FrameTypeStdin:
			if stdin == nil || stdinClosed {
				return fmt.Errorf("failed to handle %q frame: this exec session has no stdin enabled or it is already closed",
					frame.Type)
			}

			if len(frame.Data) == 0 {
				err = stdin.Close()
				stdinClosed = true
			} else {
				_, err = stdin.Write(frame.Data)
			}
			if err != nil {
				return fmt.Errorf("failed to handle %q frame: %w", frame.Type, err)
			}
		case execstream.FrameTypeResize:
			if frame.Terminal == nil {
				return fmt.Errorf("failed to handle %q frame: terminal size is required", frame.Type)
			}

			if err := exec.Resize(frame.Terminal.Rows, frame.Terminal.Cols); err != nil {
				return fmt.Errorf("failed to handle %q frame: %w", frame.Type, err)
			}
		default:
			return fmt.Errorf("unexpected frame type received: %q", frame.Type)
		}
	}
}

package controller

import (
	"context"
	"errors"
	"fmt"
	"net/http"
	"strconv"
	"time"

	"github.com/avast/retry-go/v5"
	"github.com/cirruslabs/orchard/internal/responder"
	v1 "github.com/cirruslabs/orchard/pkg/resource/v1"
	"github.com/cirruslabs/orchard/rpc"
	"github.com/gin-gonic/gin"
	"github.com/google/uuid"
)

var errIPRequest = errors.New("failed to request VM's IP")

func (controller *Controller) ip(ctx *gin.Context) responder.Responder {
	if responder := controller.authorizeAny(ctx, v1.ServiceAccountRoleComputeWrite,
		v1.ServiceAccountRoleComputeConnect); responder != nil {
		return responder
	}

	// Retrieve and parse path and query parameters
	name := ctx.Param("name")

	waitRaw := ctx.DefaultQuery("wait", "0")
	wait, err := strconv.ParseUint(waitRaw, 10, 16)
	if err != nil {
		return responder.Code(http.StatusBadRequest)
	}
	waitContext, waitContextCancel := context.WithTimeout(ctx, time.Duration(wait)*time.Second)
	defer waitContextCancel()

	// Look-up the VM
	vm, responderImpl := controller.waitForVM(waitContext, name)
	if responderImpl != nil {
		return responderImpl
	}

	// Send an IP resolution request and wait for the result
	ip, err := retry.NewWithData[string](
		retry.Context(waitContext),
		retry.DelayType(retry.FixedDelay),
		retry.Delay(time.Second),
		retry.Attempts(0),
		retry.LastErrorOnly(true),
	).Do(func() (string, error) {
		return controller.vmIP(ctx, waitContext, vm.Worker, vm.UID)
	})
	if err != nil {
		if errors.Is(err, errIPRequest) {
			controller.logger.Warnf("failed to request VM's IP from the worker %s: %v",
				vm.Worker, err)

			return responder.Code(http.StatusServiceUnavailable)
		}

		return responder.Error(err)
	}

	result := struct {
		IP string `json:"ip"`
	}{
		IP: ip,
	}

	return responder.JSON(http.StatusOK, &result)
}

func (controller *Controller) vmIP(
	ctx context.Context,
	waitContext context.Context,
	workerName string,
	vmUID string,
) (string, error) {
	// Send an IP resolution request and wait for the result.
	session := uuid.New().String()
	boomerangConnCh, cancel := controller.ipRendezvous.Request(ctx, session)
	defer cancel()

	err := controller.workerNotifier.Notify(waitContext, workerName, &rpc.WatchInstruction{
		Action: &rpc.WatchInstruction_ResolveIpAction{
			ResolveIpAction: &rpc.WatchInstruction_ResolveIP{
				Session: session,
				VmUid:   vmUID,
			},
		},
	})
	if err != nil {
		return "", fmt.Errorf("%w: failed to request VM's IP from the worker %s: %v",
			errIPRequest, workerName, err)
	}

	select {
	case rendezvousResponse := <-boomerangConnCh:
		if rendezvousResponse.ErrorMessage != "" {
			return "", fmt.Errorf("VM's IP resolution on the worker %s failed: %s",
				workerName, rendezvousResponse.ErrorMessage)
		}

		return rendezvousResponse.Result, nil
	case <-waitContext.Done():
		return "", waitContext.Err()
	}
}

package controller

import (
	"errors"
	"net/http"
	"time"

	storepkg "github.com/cirruslabs/orchard/internal/controller/store"
	"github.com/cirruslabs/orchard/internal/responder"
	"github.com/cirruslabs/orchard/internal/simplename"
	v1 "github.com/cirruslabs/orchard/pkg/resource/v1"
	"github.com/gin-gonic/gin"
)

func (controller *Controller) createWorker(ctx *gin.Context) responder.Responder {
	if responder := controller.authorize(ctx, v1.ServiceAccountRoleComputeWrite); responder != nil {
		return responder
	}

	var worker v1.Worker

	if err := ctx.ShouldBindJSON(&worker); err != nil {
		return responder.JSON(http.StatusBadRequest, NewErrorResponse("invalid JSON was provided"))
	}

	if worker.Name == "" {
		return responder.JSON(http.StatusPreconditionFailed, NewErrorResponse("worker name is empty"))
	} else if err := simplename.Validate(worker.Name); err != nil {
		return responder.JSON(http.StatusPreconditionFailed,
			NewErrorResponse("worker name %v", err))
	}

	// Provide platform defaults
	if worker.Arch == "" {
		worker.Arch = v1.ArchitectureARM64
	}
	if worker.Runtime == "" {
		worker.Runtime = v1.RuntimeTart
	}

	currentTime := time.Now()
	if worker.LastSeen.IsZero() {
		worker.LastSeen = currentTime
	}
	worker.CreatedAt = currentTime

	return controller.storeUpdate(func(txn storepkg.Transaction) responder.Responder {
		// In case there already exist a worker with the same name,
		// update it (to avoid overwriting things like SchedulingPaused)
		// if the request comes from a worker with the same machine ID
		dbWorker, err := txn.GetWorker(worker.Name)
		if err != nil {
			if errors.Is(err, storepkg.ErrNotFound) {
				// Create a new worker
				if err := txn.SetWorker(worker); err != nil {
					return responder.Error(err)
				}

				return responder.JSON(200, worker)
			}

			controller.logger.Errorf("failed to check if the worker "+
				"with name %q exists in the DB: %v", worker.Name, err)

			return responder.Code(http.StatusInternalServerError)
		}

		// Update an already existing worker
		if worker.MachineID != dbWorker.MachineID {
			return responder.JSON(http.StatusConflict, NewErrorResponse("this worker is managed "+
				"from a different machine ID, delete this worker first to be able to re-create it"))
		}

		dbWorker.Arch = worker.Arch
		dbWorker.Runtime = worker.Runtime
		dbWorker.LastSeen = worker.LastSeen
		dbWorker.Resources = worker.Resources
		dbWorker.Labels = worker.Labels
		dbWorker.DefaultCPU = worker.DefaultCPU
		dbWorker.DefaultMemory = worker.DefaultMemory
		dbWorker.Capabilities = worker.Capabilities

		if err := txn.SetWorker(*dbWorker); err != nil {
			return responder.Error(err)
		}

		return responder.JSON(200, dbWorker)
	})
}

func (controller *Controller) updateWorker(ctx *gin.Context) responder.Responder {
	if responder := controller.authorize(ctx, v1.ServiceAccountRoleComputeWrite); responder != nil {
		return responder
	}

	var userWorker v1.Worker

	if err := ctx.ShouldBindJSON(&userWorker); err != nil {
		return responder.JSON(http.StatusBadRequest, NewErrorResponse("invalid JSON was provided"))
	}

	return controller.storeUpdate(func(txn storepkg.Transaction) responder.Responder {
		dbWorker, err := txn.GetWorker(userWorker.Name)
		if err != nil {
			return responder.Error(err)
		}

		if !userWorker.LastSeen.IsZero() {
			dbWorker.LastSeen = userWorker.LastSeen
		}
		dbWorker.SchedulingPaused = userWorker.SchedulingPaused

		if err := txn.SetWorker(*dbWorker); err != nil {
			controller.logger.Errorf("failed to update worker in the DB: %v", err)

			return responder.Code(http.StatusInternalServerError)
		}

		return responder.JSON(200, &dbWorker)
	})
}

func (controller *Controller) getWorker(ctx *gin.Context) responder.Responder {
	if responder := controller.authorize(ctx, v1.ServiceAccountRoleComputeRead); responder != nil {
		return responder
	}

	name := ctx.Param("name")

	return controller.storeView(func(txn storepkg.Transaction) responder.Responder {
		worker, err := txn.GetWorker(name)
		if err != nil {
			return responder.Error(err)
		}

		return responder.JSON(http.StatusOK, &worker)
	})
}

func (controller *Controller) listWorkers(ctx *gin.Context) responder.Responder {
	if responder := controller.authorize(ctx, v1.ServiceAccountRoleComputeRead); responder != nil {
		return responder
	}

	return controller.storeView(func(txn storepkg.Transaction) responder.Responder {
		workers, err := txn.ListWorkers()
		if err != nil {
			return responder.Error(err)
		}

		return responder.JSON(http.StatusOK, &workers)
	})
}

func (controller *Controller) deleteWorker(ctx *gin.Context) responder.Responder {
	if responder := controller.authorize(ctx, v1.ServiceAccountRoleComputeWrite); responder != nil {
		return responder
	}

	name := ctx.Param("name")

	return controller.storeUpdate(func(txn storepkg.Transaction) responder.Responder {
		if err := txn.DeleteWorker(name); err != nil {
			return responder.Error(err)
		}

		return responder.Code(http.StatusOK)
	})
}

package controller

import (
	"context"
	"fmt"
	"net"
	"net/http"
	"strconv"
	"time"

	"github.com/avast/retry-go/v5"
	storepkg "github.com/cirruslabs/orchard/internal/controller/store"
	"github.com/cirruslabs/orchard/internal/netconncancel"
	"github.com/cirruslabs/orchard/internal/proxy"
	"github.com/cirruslabs/orchard/internal/responder"
	"github.com/cirruslabs/orchard/pkg/client"
	v1 "github.com/cirruslabs/orchard/pkg/resource/v1"
	"github.com/cirruslabs/orchard/rpc"
	"github.com/coder/websocket"
	"github.com/gin-gonic/gin"
	"github.com/google/uuid"
	"github.com/pkg/errors"
	"github.com/samber/lo"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"
)

var errPortForwardRequest = errors.New("failed to request port forwarding")

func (controller *Controller) portForwardVM(ctx *gin.Context) responder.Responder {
	// Retrieve and parse path and query parameters
	name := ctx.Param("name")
	portRaw := ctx.Query("port")
	hostProcess := ctx.Query("hostProcess")
	target := client.PortForwardTarget(ctx.Query("target"))
	if target != "" {
		if err := target.Validate(); err != nil {
			return responder.JSON(http.StatusBadRequest, NewErrorResponse("%v", err))
		}
		if portRaw != "" || hostProcess != "" {
			return responder.JSON(http.StatusBadRequest,
				NewErrorResponse("target cannot be combined with port or hostProcess"))
		}
		if responder := controller.authorizeAny(ctx, v1.ServiceAccountRoleComputeWrite,
			v1.ServiceAccountRoleComputeConnectTartGuestAgent); responder != nil {
			return responder
		}
	} else if responder := controller.authorizeAny(ctx, v1.ServiceAccountRoleComputeWrite,
		v1.ServiceAccountRoleComputeConnect); responder != nil {
		return responder
	}

	// Host process connections require an additional role
	var port uint64
	var err error

	if hostProcess != "" {
		if responder := controller.authorizeAny(ctx, v1.ServiceAccountRoleHostProcessWrite,
			v1.ServiceAccountRoleHostProcessConnect); responder != nil {
			return responder
		}

		// Host process forwarding cannot also target a VM port
		if portRaw != "" {
			return responder.Code(http.StatusBadRequest)
		}
	} else if target == "" {
		// VM port forwarding requires a valid non-zero TCP port
		port, err = strconv.ParseUint(portRaw, 10, 16)
		if err != nil || port < 1 || port > 65535 {
			return responder.Code(http.StatusBadRequest)
		}
	}

	waitRaw := ctx.DefaultQuery("wait", "10")
	wait, err := strconv.ParseUint(waitRaw, 10, 16)
	if err != nil {
		return responder.Code(http.StatusBadRequest)
	}

	// Look-up the VM
	waitContext, waitContextCancel := context.WithTimeout(ctx, time.Duration(wait)*time.Second)
	defer waitContextCancel()

	vm, responderImpl := controller.waitForVM(waitContext, name)
	if responderImpl != nil {
		return responderImpl
	}

	// Verify that the requested host process is declared on the VM.
	if hostProcess != "" && !lo.SomeBy(vm.HostProcesses, func(process v1.HostProcess) bool {
		return process.Name == hostProcess
	}) {
		return responder.JSON(http.StatusNotFound,
			NewErrorResponse("host process %q is not declared on VM %q", hostProcess, vm.Name))
	}

	// Commence port forwarding
	return controller.portForward(ctx, waitContext, vm.Worker, vm.UID, uint32(port), hostProcess, target)
}

func (controller *Controller) portForward(
	ctx *gin.Context,
	notifyContext context.Context,
	workerName string,
	vmUID string,
	port uint32,
	hostProcess string,
	target client.PortForwardTarget,
) responder.Responder {
	// Request and wait for a connection with a worker
	rendezvousConn, err := retry.NewWithData[net.Conn](
		retry.Context(notifyContext),
		retry.DelayType(retry.FixedDelay),
		retry.Delay(time.Second),
		retry.Attempts(0),
		retry.LastErrorOnly(true),
	).Do(func() (net.Conn, error) {
		return controller.portForwardConnection(ctx, notifyContext, workerName, vmUID, port, hostProcess, target)
	})
	if err != nil {
		if errors.Is(err, errPortForwardRequest) {
			controller.logger.Warnf("failed to request port forwarding from the worker %s: %v",
				workerName, err)

			return responder.Code(http.StatusServiceUnavailable)
		}

		return responder.Error(err)
	}
	defer func() {
		_ = rendezvousConn.Close()
	}()

	// Worker will asynchronously start port forwarding, so we wait
	wsConn, err := websocket.Accept(ctx.Writer, ctx.Request, &websocket.AcceptOptions{
		OriginPatterns: []string{"*"},
	})
	if err != nil {
		return responder.Error(err)
	}
	defer func() {
		// Ensure that we always close the accepted WebSocket connection,
		// otherwise resource leak is possible[1]
		//
		// [1]: https://github.com/coder/websocket/issues/445#issuecomment-2053792044
		_ = wsConn.CloseNow()
	}()

	expectedMsgType := websocket.MessageBinary

	// Backwards compatibility with older Orchard clients
	// using "golang.org/x/net/websocket" package
	if ctx.Request.Header.Get("User-Agent") == "" {
		expectedMsgType = websocket.MessageText
	}

	proxyConnectionsErrCh := make(chan error, 1)
	wsConnAsNetConn := websocket.NetConn(ctx, wsConn, expectedMsgType)

	go func() {
		proxyConnectionsErrCh <- proxy.Connections(wsConnAsNetConn, rendezvousConn)
	}()

	for {
		select {
		case err := <-proxyConnectionsErrCh:
			if err != nil {
				var websocketCloseError websocket.CloseError

				// Normal closure from the user
				if errors.As(err, &websocketCloseError) && websocketCloseError.Code == websocket.StatusNormalClosure {
					return responder.Empty()
				}

				if errors.Is(err, context.Canceled) {
					return responder.Empty()
				}

				if status, ok := status.FromError(err); ok && status.Code() == codes.Canceled {
					return responder.Empty()
				}

				controller.logger.Warnf("port forwarding: failed to proxy connections: %v", err)
			}

			return responder.Empty()
		case <-time.After(controller.pingInterval):
			pingCtx, pingCtxCancel := context.WithTimeout(ctx, 5*time.Second)

			if err := wsConn.Ping(pingCtx); err != nil {
				controller.logger.Warnf("port forwarding: failed to ping the client, "+
					"connection might time out: %v", err)
			}

			pingCtxCancel()
		}
	}
}

func (controller *Controller) waitForVM(ctx context.Context, name string) (*v1.VM, responder.Responder) {
	var vm *v1.VM
	var err error

	for {
		if lookupResponder := controller.storeView(func(txn storepkg.Transaction) responder.Responder {
			vm, err = txn.GetVM(name)
			if err != nil {
				return responder.Error(err)
			}

			return nil
		}); lookupResponder != nil {
			return nil, lookupResponder
		}

		if vm.TerminalState() {
			return nil, responder.JSON(http.StatusExpectationFailed,
				NewErrorResponse("VM is in a terminal state '%s'", vm.Status))
		}
		if vm.Status == v1.VMStatusRunning {
			// VM is running, proceed
			return vm, nil
		}
		select {
		case <-ctx.Done():
			return nil, responder.JSON(http.StatusRequestTimeout,
				NewErrorResponse("VM is not running on '%s' worker", vm.Worker))
		case <-time.After(1 * time.Second):
			// try again
			continue
		}
	}
}

func (controller *Controller) portForwardConnection(
	ctx context.Context,
	waitContext context.Context,
	workerName string,
	vmUID string,
	port uint32,
	hostProcess string,
	target client.PortForwardTarget,
) (net.Conn, error) {
	// Create a rendezvous connection point
	rendezvousCtx, rendezvousCtxCancel := context.WithCancel(ctx)

	session := uuid.New().String()
	boomerangConnCh, boomerangConnCancel := controller.connRendezvous.Request(rendezvousCtx, session)

	cancel := func() {
		boomerangConnCancel()
		rendezvousCtxCancel()
	}

	// Send request to a worker to initiate a port forwarding connection back to us
	portForwardAction := &rpc.WatchInstruction_PortForward{
		Session: session,
	}
	if hostProcess != "" {
		portForwardAction.Target = &rpc.WatchInstruction_PortForward_Target{
			Value: &rpc.WatchInstruction_PortForward_Target_HostProcess_{
				HostProcess: &rpc.WatchInstruction_PortForward_Target_HostProcess{
					VmUid: vmUID,
					Name:  hostProcess,
				},
			},
		}
	} else if target == client.PortForwardTargetTartGuestAgent {
		portForwardAction.Target = &rpc.WatchInstruction_PortForward_Target{
			Value: &rpc.WatchInstruction_PortForward_Target_TartGuestAgent_{
				TartGuestAgent: &rpc.WatchInstruction_PortForward_Target_TartGuestAgent{VmUid: vmUID},
			},
		}
	} else {
		portForwardAction.VmUid = vmUID
		portForwardAction.Port = port
	}
	err := controller.workerNotifier.Notify(waitContext, workerName, &rpc.WatchInstruction{
		Action: &rpc.WatchInstruction_PortForwardAction{
			PortForwardAction: portForwardAction,
		},
	})
	if err != nil {
		cancel()

		return nil, fmt.Errorf("%w: failed to request port forwarding from the worker %s: %v",
			errPortForwardRequest, workerName, err)
	}

	// Wait for the worker to respond
	select {
	case rendezvousResponse := <-boomerangConnCh:
		if rendezvousResponse.ErrorMessage != "" {
			cancel()

			return nil, fmt.Errorf("failed to establish port forwarding session on the worker: %s",
				rendezvousResponse.ErrorMessage)
		}

		return netconncancel.New(rendezvousResponse.Result, cancel), nil
	case <-waitContext.Done():
		cancel()

		return nil, waitContext.Err()
	}
}
